<?php
/** Phase 10 — article quality and content intelligence; advisory, transparent checks only. */
if (!defined('ABSPATH')) exit;
if (!class_exists('BSW_Phase10_Quality_Intelligence')) {
final class BSW_Phase10_Quality_Intelligence {
 public static function init(){add_action('add_meta_boxes_wiki_article',array(__CLASS__,'box'),20);add_shortcode('bsw_article_quality',array(__CLASS__,'shortcode'));add_action('admin_menu',array(__CLASS__,'menu'),80);add_action('admin_enqueue_scripts',array(__CLASS__,'css'));}
 private static function analyse($p){$raw=(string)$p->post_content;$text=trim(preg_replace('/\s+/u',' ',wp_strip_all_tags(strip_shortcodes($raw))));$words=preg_match_all('/[\p{L}\p{N}]+/u',$text,$m);$words=(int)$words;$sentences=preg_split('/(?<=[.!?])\s+/u',$text,-1,PREG_SPLIT_NO_EMPTY);$headings=0;preg_match_all('/<h[2-4]\b|^==+[^=].*?==+\s*$/mi',$raw,$hm);$headings=count($hm[0]);$sources=0;if(preg_match_all('/https?:\/\/[^\s\]\)"\']+/i',$raw,$urls))$sources=count(array_unique($urls[0]));if(class_exists('BSW_Phase6_Citation_Management')){$sources=max($sources,count((array)get_post_meta($p->ID,'_bsw_p6_sources',true)));}$checks=array('Useful article length'=>array($words>=300,'300+ words',$words.' words'),'Lead summary'=>array(strlen(trim($p->post_excerpt))>=80||$words>=120,'Summary or substantive opening',strlen(trim($p->post_excerpt)).' summary characters'),'Section structure'=>array($headings>=2,'At least 2 section headings',$headings.' headings'),'Source signals'=>array($sources>=2,'At least 2 detected source URLs',$sources.' URLs detected'),'Featured image'=>array(has_post_thumbnail($p->ID),'Featured image',has_post_thumbnail($p->ID)?'Present':'Missing'),'Readable paragraph structure'=>array(substr_count($raw,'</p>')>=2||$words<180,'Two or more paragraphs for longer articles',substr_count($raw,'</p>').' paragraph endings'),'No obvious duplicate long sentences'=>array(self::duplicates($text)===0,'No exact repeated long sentences',self::duplicates($text).' detected'));$passed=0;foreach($checks as $c)if($c[0])$passed++;return array('words'=>$words,'sentences'=>count($sentences),'checks'=>$checks,'passed'=>$passed,'total'=>count($checks),'score'=>(int)round(100*$passed/count($checks)));}
 private static function duplicates($text){$s=preg_split('/(?<=[.!?])\s+/u',$text,-1,PREG_SPLIT_NO_EMPTY);$seen=array();$n=0;foreach($s as $v){$k=function_exists('mb_strtolower')?mb_strtolower(trim($v),'UTF-8'):strtolower(trim($v));if(strlen($k)<55)continue;if(isset($seen[$k]))$n++;$seen[$k]=1;}return $n;}
 private static function markup($p){$a=self::analyse($p);$o='<div class="bsw-p10-quality"><p><strong>Advisory quality score: '.(int)$a['score'].'/100</strong> <span>('.(int)$a['passed'].' of '.(int)$a['total'].' checks)</span></p><div class="bsw-p10-meter" role="img" aria-label="Quality checks passed: '.(int)$a['score'].' percent"><span style="width:'.(int)$a['score'].'%"></span></div><p class="description">'.(int)$a['words'].' words · '.(int)$a['sentences'].' sentences. This score measures detectable structure only; it does not verify facts, neutrality, notability or source reliability.</p><ul>';foreach($a['checks'] as $name=>$c)$o.='<li><span class="'.($c[0]?'pass':'needs').'">'.($c[0]?'✓':'!').'</span> <strong>'.esc_html($name).'</strong><small>'.esc_html($c[2]).' · '.esc_html($c[1]?'Target met':'Suggested: '.$c[1]).'</small></li>';return $o.'</ul></div>';}
 public static function box(){add_meta_box('bsw_p10_quality','BIGSHOR Content Intelligence',array(__CLASS__,'render'),'wiki_article','side','high');}
 public static function render($p){echo self::markup($p);}
 public static function shortcode($atts){$a=shortcode_atts(array('id'=>get_the_ID()),$atts,'bsw_article_quality');$p=get_post(absint($a['id']));if(!$p||$p->post_type!=='wiki_article')return '';if(!current_user_can('edit_post',$p->ID))return '';return self::markup($p);}
 public static function menu(){add_submenu_page('edit.php?post_type=wiki_article','Content Intelligence','Content Intelligence','edit_others_posts','bsw-p10-intelligence',array(__CLASS__,'page'));}
 public static function page(){if(!current_user_can('edit_others_posts'))wp_die('Permission denied.',403);$q=new WP_Query(array('post_type'=>'wiki_article','post_status'=>array('publish','pending','draft','future'),'posts_per_page'=>100,'orderby'=>'modified','order'=>'DESC','no_found_rows'=>true));echo '<div class="wrap"><h1>BIGSHOR Content Intelligence</h1><p>Advisory structural checks for the latest 100 articles. Scores are not fact-checks or publication gates.</p><table class="widefat striped"><thead><tr><th>Article</th><th>Status</th><th>Words</th><th>Checks passed</th><th>Score</th></tr></thead><tbody>';while($q->have_posts()){$q->the_post();$p=get_post();$a=self::analyse($p);echo '<tr><td><a href="'.esc_url(get_edit_post_link($p->ID)).'">'.esc_html(get_the_title($p)).'</a></td><td>'.esc_html($p->post_status).'</td><td>'.(int)$a['words'].'</td><td>'.(int)$a['passed'].'/'.(int)$a['total'].'</td><td>'.(int)$a['score'].'/100</td></tr>'; }wp_reset_postdata();echo '</tbody></table></div>';}
 public static function css($hook){if(!in_array($hook,array('post.php','post-new.php','edit.php'),true))return;wp_register_style('bsw-p10-admin',false,array(),'31.5.0');wp_enqueue_style('bsw-p10-admin');wp_add_inline_style('bsw-p10-admin','.bsw-p10-quality{font-size:12px}.bsw-p10-quality ul{list-style:none;margin:8px 0}.bsw-p10-quality li{padding:7px 0;border-bottom:1px solid #eee}.bsw-p10-quality small{display:block;color:#646970;margin-left:23px}.bsw-p10-quality .pass{color:#16834a;font-weight:700}.bsw-p10-quality .needs{color:#b36b00;font-weight:700}.bsw-p10-meter{height:7px;background:#e5e7eb;border-radius:8px;overflow:hidden}.bsw-p10-meter span{display:block;height:100%;background:#315d89}');}
}
BSW_Phase10_Quality_Intelligence::init();
}
